// Icons from the Paper design. All are stroke-based, 24-unit viewBox unless noted,
// and inherit `currentColor` so the CSS controls color and dark mode.
import type { SVGProps } from 'react'

type IconProps = SVGProps<SVGSVGElement>

const stroke = {
  fill: 'none',
  stroke: 'currentColor',
  strokeWidth: 1.5,
  strokeLinecap: 'round',
  strokeLinejoin: 'round',
} as const

function Svg({ viewBox = '0 0 24 24', children, ...rest }: IconProps) {
  return (
    <svg viewBox={viewBox} aria-hidden="true" focusable="false" {...rest}>
      {children}
    </svg>
  )
}

